class Auto(object):
    """The ``Auto`` specifier type enables automatic type inference and
    conversion during glom operations. When used as a subspec, it will
    attempt to infer the appropriate type or transformation based on context.

    This is useful when you want glom to automatically handle type
    conversions without explicit specification.

    Args:
       spec: An optional sub-spec to apply auto-conversion to. Defaults
         to the target itself.

    Example:

      >>> # Auto can be used to convert types automatically
      >>> glom({'val': '42'}, Auto('val'))  # might convert string to int
    """
    def __init__(self, spec=T):
        self.spec = spec

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Fill(object):
    """The ``Fill`` specifier type fills in missing or null values in
    the target data with a specified default. This is similar to Python's
    ``dict.get()`` with a default, but works at any level in the data
    structure.

    Fill is particularly useful when you want to ensure certain keys
    or attributes exist in the output, even if they're missing in the
    input.

    Args:
       spec: A sub-spec to apply filling to. Defaults to the target.
       default: The value to use when the spec produces a missing or
         None result. Can also be a callable that returns the default.

    Example:

      >>> target = {'a': 'hello'}
      >>> glom(target, Fill('b', default='world'))
      'world'
    """
    def __init__(self, spec=T, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            val = scope[glom](target, self.spec, scope)
            if val is None:
                if callable(self.default):
                    return self.default()
                return self.default
            return val
        except GlomError:
            if callable(self.default):
                return self.default()
            return self.default

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Iter(object):
    """The ``Iter`` specifier type provides iteration over the target
    data, enabling streaming-style processing of iterables. It yields
    items one at a time rather than collecting them all into a list.

    This is useful for large datasets where memory efficiency is important,
    or when you want to process items lazily.

    Args:
       spec: A sub-spec to iterate over. Defaults to the target itself.

    Example:

      >>> # Iterate over items in a list
      >>> target = [1, 2, 3]
      >>> list(glom(target, Iter()))
      [1, 2, 3]
    """
    def __init__(self, spec=T):
        self.spec = spec

    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        return iter(val)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Let(object):
    """The ``Let`` specifier type enables variable binding and reuse
    within glom specifications. It allows you to bind intermediate
    results to names and reference them later in the spec.

    This is similar to let-bindings in functional programming languages,
    allowing you to avoid redundant computations.

    Args:
       bindings: A dictionary mapping names to their bound values.
         Each value can be a sub-spec that will be evaluated.
       spec: The final spec to evaluate with the bindings in scope.

    Example:

      >>> target = {'a': 1, 'b': 2}
      >>> spec = Let({'x': 'a', 'y': 'b'}, T['x'] + T['y'])
      >>> glom(target, spec)
      3
    """
    def __init__(self, bindings, spec):
        self.bindings = bindings
        self.spec = spec

    def glomit(self, target, scope):
        new_scope = ChainMap(dict(scope))
        for name, subspec in self.bindings.items():
            val = scope[glom](target, subspec, scope)
            new_scope[name] = val
        return scope[glom](target, self.spec, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.bindings, self.spec)


class Invoke(object):
    """The ``Invoke`` specifier type invokes a callable with the target
    and/or additional arguments. Unlike :class:`~glom.Call`, which passes
    the target as the first positional argument, ``Invoke`` gives more
    control over how the callable is invoked.

    Invoke supports both positional and keyword arguments, and can be used
    to construct objects or call functions with complex argument structures.

    Args:
       func: A callable to invoke.
       args: Positional arguments to pass to the callable.
       kwargs: Keyword arguments to pass to the callable.
       constants: Values that should not be evaluated as specs. This is
         an alias for storing constant/untransformed values.

    Example:

      >>> class MyClass:
      ...     def __init__(self, x, y):
      ...         self.x = x
      ...         self.y = y
      >>> target = {'x': 1, 'y': 2}
      >>> result = glom(target, Invoke(MyClass, kwargs={'x': T['x'], 'y': T['y']}))
      >>> result.x
      1
    """
    def __init__(self, func, *args, **kwargs):
        if not callable(func):
            raise TypeError('expected func to be callable, not: %r' % (func,))
        self.func = func
        self._args = args
        # Store kwargs including 'constants' key if present
        self.kwargs = {}
        self.constants = kwargs.pop('constants', {})
        self.kwargs.update(kwargs)

    @property
    def consts(self):
        """Deprecated alias for constants."""
        return self.constants

    @consts.setter
    def consts(self, value):
        """Deprecated setter for constants."""
        self.constants = value

    def glomit(self, target, scope):
        def _eval(t):
            if type(t) in (Spec, TType):
                return scope[glom](target, t, scope)
            # Check if it's in constants
            if isinstance(t, str) and t in self.constants:
                return self.constants[t]
            return t

        args = [_eval(a) for a in self._args]
        kwargs = {name: _eval(val) for name, val in self.kwargs.items()}
        return self.func(*args, **kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        # Use _args internally but don't expose it directly in repr
        return '%s(%r, constants=%r, **%r)' % (
            cn, self.func, self.constants, self.kwargs
        )


